INSERT IGNORE INTO `sys_texts` (`id`, `alias`, `lang`, `context`) VALUES
(713, 'telegram_ask_time_working', 'ru', '<b>Когда вам удобно получать уведомления по будням?</b>\n\nВведите интервал времени в формате:\n<blockquote>10:00-01:00\nили\n07:15-22:45</blockquote>\n\n<i>В этот период я буду отправлять системные напоминания и ежедневные сводки.  \nВаши собственные уведомления будут приходить и вне этого интервала.</i>\n\n<b>Ваш часовой пояс:</b> <i>{#TIMEZONE#}</i>\n<b>Текущее время уведомлений:</b> <i>{#TIME#}</i>'),
(714, 'telegram_ask_time_holidays', 'ru', '<b>Когда вам удобно получать уведомления по выходным (праздникам)?</b>\r\n\r\nВведите интервал времени в формате:\r\n<blockquote>10:00-01:00\r\nили\r\n07:15-22:45</blockquote>\r\n\r\n<i>В это время я буду отправлять напоминания и ежедневные сводки.</i>\r\n\r\n<b>Вы используете часовой пояс:</b> <i>{#TIMEZONE#}</i>\r\n<b>Текущее время уведомлений:</b> <i>{#TIME#}</i>'),
(715, 'ask_time_working', 'ru', 'Когда вам удобно получать уведомления по будням (рабочим дням)?\r\n\r\nВведите интервал времени в формате:\r\n10:00-01:00\r\nили\r\n07:15-22:45\r\n\r\nВ это время я буду отправлять напоминания и ежедневные сводки.\r\n\r\nВы используете часовой пояс: {#TIMEZONE#}\r\nТекущее время уведомлений: {#TIME#}'),
(717, 'ask_time_holidays', 'ru', 'Когда вам удобно получать уведомления по выходным (праздникам)?\r\n\r\nВведите интервал времени в формате:\r\n10:00-01:00\r\nили\r\n07:15-22:45\r\n\r\nВ это время я буду отправлять напоминания и ежедневные сводки.\r\n\r\nВы используете часовой пояс: {#TIMEZONE#}\r\nТекущее время уведомлений: {#TIME#}'),
(718, 'error_wrong_time_range', 'ru', 'Вы ввели неверный формат часового диапазона.'),
(719, 'telegram_error_wrong_time_range', 'ru', '<i>Вы ввели неверный формат часового диапазона.</i>'),
(720, 'end_of_profile_settings', 'ru', 'Настройка профиля завершена.\n\nДавайте создадим первую задачу, событие или заметку ✨'),
(721, 'telegram_end_of_profile_settings', 'ru', '<i>Настройка профиля завершена.</i>\n\n<b>Давайте создадим первую задачу, событие или заметку ✨</b>'),
(722, 'btn_task_event_emo', 'ru', '✚ Задача/Событие'),
(723, 'btn_memory_emo', 'ru', '✚ Заметка ▼'),
(724, 'btn_file_emo', 'ru', '📄 Файл'),
(725, 'btn_search_emo', 'ru', '🔍 Поиск'),
(726, 'btn_profile_emo', 'ru', '👤 Профиль'),
(727, 'telegram_choose_action_from_button_menu', 'ru', '<b>Что вы хотите сделать?</b>\r\n\r\nВыберите действие:\r\n\r\n• Создать <b>задачу или событие</b> (разовое или повторяющееся)  \r\n• <b>Сохранить файл</b>  \r\n• Создать <b>заметку</b> (контакт, список, запись в дневник или любую текстовую информацию)  \r\n• <b>Найти</b> задачу, заметку, список или файл по тексту и/или тегам  \r\n• <b>Изменить данные профиля</b>'),
(728, 'choose_action_from_button_menu', 'ru', 'Что вы хотите сделать?\r\n\r\nВыберите действие:\r\n\r\n• Создать задачу или событие (разовое или повторяющееся)  \r\n• Сохранить файл \r\n• Создать заметку (контакт, список, запись в дневник или любую текстовую информацию)  \r\n• Найти задачу, заметку, список или файл по тексту и/или тегам  \r\n• Изменить данные профиля'),
(731, 'telegram_start_norm', 'ru', '<b>Что вы хотите сделать?</b>\r\n\r\nСоздать задачу, событие, заметку или сохранить файл.\r\n\r\nВ заметки входят списки, записи в дневник и любые другие текстовые записи, например, контакты людей.\r\n\r\nТакже вы можете найти нужную информацию или изменить данные профиля.'),
(732, 'start_norm', 'ru', 'Что вы хотите сделать?\r\n\r\nСоздать задачу, событие, заметку или сохранить файл.\r\n\r\nВ заметки входят списки, записи в дневник и любые другие текстовые записи, например, контакты людей.\r\n\r\nТакже вы можете найти нужную информацию или изменить данные профиля.'),
(733, 'telegram_list_step_name', 'ru', '<i><b>Название</b> · Список · Теги</i>'),
(734, 'telegram_list_step_list', 'ru', '<i>✓Название · <b>Список</b> · Теги</i>'),
(735, 'telegram_list_step_tags', 'ru', '<i>✓Название · ✓Список · <b>Теги</b></i>'),
(736, 'telegram_listing', 'ru', '<b>Пошаговое создание списка</b>'),
(737, 'telegram_list_change_name', 'ru', '<i>Вы можете изменить название списка. Введите новое название списка.</i>\n\n<b>Текущее:</b> <i>{#TITLE#}</i>'),
(738, 'telegram_list_enter_name', 'ru', '<b>Как назовём список?</b>\n\n<i>Например: «Покупки», «Список дел», «Собрать в чемодан».</i>'),
(739, 'telegram_list_enter_items_with_old', 'ru', '<b>Ваш список:</b>\n{#LIST#}\n\n<b>Дополните список новыми элементами, отправив их боту или пропустите шаг. Вы также можете отредактировать или удалить уже существующие элементы списка.</b>\n\n<code>Формат ввода:</code>\n<code>• через запятую, или</code>\n<code>• каждый элемент с новой строки</code>\n\n<i>Используйте только один из форматов. Если в элементе списка есть запятые — используйте перенос строки.</i>'),
(740, 'telegram_list_enter_items', 'ru', '<b>Добавьте элементы списка.</b>\n\n<i>Формат ввода:</i>\n<b>• через запятую</b> <i>или</i>\n<b>• каждый элемент с новой строки</b>\n\n<i>Если в элементе списка есть запятые — используйте перенос строки.</i>\n\n<b>Список пока пуст. Введите и отправьте его мне.</b>'),
(741, 'telegram_list_enter_tags', 'ru', '<b>Добавьте теги, чтобы список было легче найти.</b>\n\n<i>Введите теги через запятую.\nНапример: покупки, путешествие.</i>\n\n<i>Этот шаг можно пропустить.</i>\n\n<b>Ваши теги:</b> {#TAGS#}'),
(742, 'empty_tags', 'ru', 'Теги не добавлены.'),
(743, 'telegram_empty_tags', 'ru', '<i>Теги не добавлены.</i>'),
(744, 'tide_with', 'ru', '🔗 Связать с…'),
(745, 'telegram_list_enter_search', 'ru', '<b>Поиск списка</b>\r\n\r\nОтправьте мне тег или слово из названия списка или его элементов, чтобы бот нашёл нужный список.\r\n\r\nИли нажмите кнопку <b>Показать все списки</b>. Списки выводятся по 10 штук на страницу.'),
(746, 'telegram_list_start', 'ru', 'Выберите, что хотите сделать: создать новый список или найти существующий.\r\n\r\n<b>Нажмите на один из вариантов ниже:</b>'),
(747, 'telegram_list_action_choose', 'ru', 'Выберите, что хотите сделать: создать новый список или найти существующий.\r\n\r\n<b>Нажмите на один из вариантов ниже:</b>'),
(748, 'create_list_emo', 'ru', '✚ Список'),
(749, 'find_list_emo', 'ru', '🔍 Найти список'),
(750, 'show_all_lists_emo', 'ru', '☰ Показать все списки'),
(751, 'telegram_lists_show', 'ru', '<b>Поиск списков</b>\n<i>Это постраничный вывод всех ваших списков. Вы можете:</i>\n\n<code>• Отправить боту номер списка на странице, или</code>\n<code>• Использовать кнопки для перехода между страницами, если их больше одной</code>\n\n<b>Страница {#PAGE#}/{#MAXPAGE#}</b>\n\n{#LISTS#}\n\n\n'),
(752, 'telegram_lists_show_search', 'ru', '<b>Поиск списка</b>\r\n\r\nЗдесь показаны <b>30 самых релевантных результатов</b> для вашего запроса.  \r\nОтправьте боту номер списка, чтобы открыть его.\r\n\r\n{#LISTS#}\r\n'),
(753, 'telegram_edit_listing', 'ru', '<b>Пошаговое редактирование списка</b>'),
(754, 'telegram_edit_list_items', 'ru', '<b>Редактирование списка</b>\r\n\r\n{#LIST#}\r\n\r\n<i>Отправьте номер элемента, который хотите отредактировать.</i>'),
(755, 'telegram_delete_list_items', 'ru', '<b>Удаление элементов списка</b>\r\n\r\n{#LIST#}\r\n\r\n<i>Будьте внимательны: удаление происходит безвозвратно.</i>\r\n\r\n<i>Введите номер элемента списка, который нужно удалить.</i>'),
(756, 'telegram_list_item_deleted_successfully', 'ru', '<i>Элемент списка \"{#ITEM#}\" удалён.</i>'),
(758, 'telegram_list_not_exists_for_edit', 'ru', '<i>Вы редактируете несуществующий список</i>'),
(759, 'telegram_edit_list_item_success', 'ru', '<i>Список успешно отредактирован.</i>'),
(760, 'telegram_wrong_list_item_new_title', 'ru', '<i>Произошла ошибка при редактировании элемента списка. Попробуйте ещё раз.</i>'),
(761, 'telegram_enter_edit_list_item', 'ru', '<b>Введите новое значение для пункта списка.</b>\r\n\r\nТекущее значение: <i>{#ITEM#}</i>'),
(762, 'telegram_edit_list_tags', 'ru', '<b>Редактирование тегов</b>\r\n\r\n{#LIST#}\r\n\r\n<i>Отправьте номер тега, который хотите отредактировать.</i>'),
(763, 'telegram_delete_list_tags', 'ru', '<b>Удаление тегов</b>\r\n\r\n{#LIST#}\r\n\r\n<i>Будьте внимательны: удаление происходит безвозвратно.</i>\r\n\r\n<i>Отправьте номер тега, который хотите удалить.</i>'),
(764, 'telegram_enter_edit_list_tag', 'ru', '<b>Отправьте новое значение тега.</b>\r\n\r\nТекущее значение: <i>{#TAG#}</i>'),
(765, 'telegram_list_tag_deleted_successfully', 'ru', '<i>Тег <b>{#ITEM#}</b> успешно удалён.</i>'),
(766, 'telegram_list_was_created_ask', 'ru', '<b>Список создан</b>\n\nНазвание: <b>\"{#TITLE#}\"</b>:\n\n{#LIST#}\n\n{#TAGS#}\n\nХотите связать его с другой сущностью?'),
(767, 'telegram_list_was_edited_ask', 'ru', '<b>Список отредактирован</b>\r\n\r\nНазвание: <b>\"{#TITLE#}\"</b>:\r\n\r\n{#LIST#}\r\n\r\n{#TAGS#}\r\n\r\nХотите связать его с другой сущностью?'),
(768, 'telegram_list_was_created', 'ru', '<b>Список создан</b>\r\n\r\nНазвание: <b>\"{#TITLE#}\"</b>:\r\n\r\n{#LIST#}\r\n\r\n{#TAGS#}'),
(769, 'telegram_tasking', 'ru', '<b>Пошаговое создание задачи</b>'),
(770, 'telegram_eventing', 'ru', '<b>Пошаговое создание события</b>'),
(771, 'telegram_task_step_type', 'ru', '<i><b>Тип</b> · Название · Описание · Теги · Даты · Напоминания</i>'),
(772, 'telegram_task_step_name', 'ru', '<i>✓Тип · <b>Название</b> · Описание · Теги · Даты · Напоминания</i>'),
(773, 'telegram_task_step_description', 'ru', '<i>✓Тип · ✓Название · <b>Описание</b> · Теги · Даты · Напоминания</i>'),
(774, 'telegram_task_step_tags', 'ru', '<i>✓Тип · ✓Название · ✓Описание · <b>Теги</b> · Даты · Напоминания</i>'),
(775, 'telegram_task_step_repeating', 'ru', '<i>✓Тип · ✓Название · ✓Описание · ✓Теги · <b>Даты</b> · Напоминания</i>'),
(776, 'telegram_task_step_reminders', 'ru', '<i>✓Тип · ✓Название · ✓Описание · ✓Теги · ✓Даты · <b>Напоминания</b></i>'),
(777, 'delete_tags_emo', 'ru', '✂️ Удалить теги'),
(778, 'telegram_enter_deadline_event', 'ru', 'Введите дату события (с временем начала или без)\r\n\r\n<i>Примеры:</i>\r\n10.06.2030 18:00  \r\n10 июня 2030 в 18:00  \r\nиюнь 10, 18:00 — <i>если дата уже прошла, будет выбран следующий год</i>'),
(779, 'telegram_enter_period_start_event', 'ru', 'Введите дату начала события.\n\n<i>Вы можете указать время — тогда напоминания будут точнее.</i>\n\n<i>Примеры:</i>\n18.09.2025  \n18 сентября, 15:00'),
(780, 'telegram_enter_period_end_event', 'ru', 'Введите дату окончания события (с временем или без).\n\n<i>Примеры:</i>\n20.09.2030  \n20 сентября, 20:00'),
(781, 'telegram_enter_period_end', 'ru', 'Введите крайний срок выполнения задачи (дату с временем или без)\r\n\r\n<i>Примеры:</i>\r\n20.09.2030  \r\n20 сентября, 20:00'),
(782, 'telegram_enter_edit_deadline_event', 'ru', '<b>Введите новую дату события или нажмите «Пропустить».</b>\n\n<i>Вы можете указать время — тогда напоминания будут точнее.</i>\n\n<i>Примеры:</i>\n2030-06-10 18:00:00  \n10.06.2030 18:00  \n10 июня 2030 в 18:00  \nиюнь 10, 18:00\n\n<b>Текущее значение:</b>  {#DATE#}'),
(783, 'telegram_enter_edit_period_start_event', 'ru', '<b>Введите новую дату начала события или нажмите Пропустить.</b>\n\n<i>Вы можете указать время — тогда напоминания будут точнее.</i>\n\n<i>Примеры:</i>\n18.09.2030\n18 сентября - <i>возьмется ближайшая дата</i>  \n2030-09-18 10:00\n\n<b>Текущее значение:</b> {#DATE#}'),
(784, 'telegram_enter_edit_period_end_event', 'ru', '<b>Введите новую дату окончания события (можно со временем).</b>\n\n<i>Примеры:</i>\n20.09.2030  \n20 сентября  \n2030-09-20 10:00\n\n<b>Текущее значение:</b> {#DATE#}'),
(785, 'telegram_enter_edit_period_end', 'ru', 'Введите новую дату дедлайна задачи (можно со временем)\r\n\r\n<i>Примеры:</i>\r\n20.09.2030  \r\n20 сентября  \r\n2030-09-20 10:00\r\n\r\n<b>Текущее значение:</b> {#DATE#}'),
(786, 'telegram_enter_repeat_every_n_days', 'ru', '<b>Введите число дней между повторами.</b>\n\n<code>0 — ежедневно</code>\n<code>1 — через день</code> \n<code>2 — через два дня</code>\n\n<i>Отправьте число боту.</i>'),
(787, 'telegram_ask_reminder_interval_event', 'ru', '<b>Добавьте напоминание или нажмите Пропустить.</b>\r\n\r\n<i>Выберите, за сколько времени до начала события напомнить.</i>'),
(788, 'telegram_ask_reminder_interval_task', 'ru', 'Добавьте напоминание до наступления дедлайна задачи.\r\n\r\n<i>Выберите, за сколько часов (если указано время), дней, недель или месяцев до дедлайна напомнить.</i>'),
(789, 'telegram_choose_week_days_enter', 'ru', 'Выберите дни недели.\n\n<i>Галками отмечены уже выбранные дни</i>'),
(790, 'telegram_choose_week_days_task', 'ru', 'Выберите дни недели, когда необходимо выполнить задачу\n\n<i>Галками отмечены уже выбранные дни</i>'),
(791, 'telegram_choose_week_days_event', 'ru', '<b>Выберите дни недели, когда будет происходить ваше событие.</b>\n\n<i>Галками отмечены уже выбранные дни</i>'),
(792, 'telegram_ask_monthly_repeats_need_time_event', 'ru', '<b>Добавить время события?</b>\n\n<i>Это нужно, если событие привязано к конкретному времени (например, мероприятие в 18:00).</i>\n\nМожно задать:\n• одно время для всех выбранных дней  \n• разное время для каждого дня\n• не указывать вовсе\n\n<i><b>Важно:</b> для диапазона дней время установить нельзя.</i>'),
(793, 'telegram_ask_monthly_repeats_need_time_task', 'ru', '<b>Добавить время дедлайна?</b>\r\n\r\n<i>Это нужно, если задачу необходимо выполнить не до конца дня а к определённому времени.</i>\r\n\r\nМожно задать:\r\n• одно время для всех выбранных дней  \r\n• разное время для каждого дня\r\n• не указывать время — тогда задачу нужно выполнить до конца дня\r\n\r\n<i><b>Важно:</b> для диапазона дней время установить нельзя.</i>'),
(794, 'telegram_choose_month_in_quarter_event', 'ru', '<b>Месяц в квартале</b>\r\n<i>Выберите месяц квартала, в котором произойдёт событие.</i>'),
(795, 'telegram_choose_start_month_in_quarter_event', 'ru', '<b>Месяц в квартале</b>\r\n<i>Выберите месяц квартала, в котором начнётся событие</i>'),
(796, 'telegram_choose_end_month_in_quarter_event', 'ru', '<b>Месяц в квартале</b>\r\n<i>Выберите месяц квартала, в котором закончится событие.</i>'),
(798, 'telegram_choose_month_in_year_event', 'ru', '<b>Укажите месяц, в котором произойдёт событие <i>(от 1 до 12)</i></b>'),
(800, 'telegram_enter_day_in_year_month_event', 'ru', '<b>Укажите день месяца события <i>(число от 1 до 31)</i></b>'),
(801, 'telegram_choose_start_month_in_year_event', 'ru', '<b>Укажите месяц начала события <i>(от 1 до 12)</i></b>'),
(802, 'telegram_choose_end_month_in_year_event', 'ru', '<b>Укажите месяц окончания события <i>(от 1 до 12)</i></b>'),
(803, 'telegram_repeat_type_new_task', 'ru', '<b>{#TYPE#}.</b>\r\nПериод выполнения: <b>с {#DATE1#} по {#DATE2#}.</b>'),
(804, 'repeat_type_new_task', 'ru', '{#TYPE#}.\n\nПериод выполнения: с {#DATE1#} по {#DATE2#}.'),
(805, 'repeat_type_new_event', 'ru', '{#TYPE#}.\n\nНачнётся: {#DATE1#}{#DATE2#}\n'),
(806, 'repeat_type_new_event_end', 'ru', 'Завершится: {#DATE#}\n'),
(807, 'one_time_task_string', 'ru', 'Единоразовая задача'),
(808, 'telegram_repeat_type_new_event', 'ru', '<b>{#TYPE#}.</b>\nНачнётся: <b>{#DATE1#}</b>{#DATE2#}\n'),
(809, 'year_rod', 'ru', 'года'),
(810, 'telegram_repeat_type_new_event_end', 'ru', 'Завершится: <b>{#DATE#}</b>\n'),
(812, 'in', 'ru', 'в'),
(813, 'at_time', 'ru', 'в'),
(814, 'telegram_chosen_repeating_type', 'ru', '<b>Текущий выбор</b>: {#TYPE#}.\n{#DESCRIPTION#}\n\nВы можете изменить его или оставить.'),
(815, 'current_choose', 'ru', 'Текущий выбор:'),
