(867, 'note_rod', 'ru', 'Заметки'),
(868, 'telegram_note_change_description_2', 'ru', '<b>Редактирование описания</b>\r\n\r\n<i>Текущее описание:</i>\r\n{#DESCRIPTION#}\r\n\r\n<i>Введите новое описание и отправьте боту</i>'),
